        {"key": "type", "value": "text"},
        {"key": "value", "value": "Jane Doe"}
      ],
      "children": []
    },
    {
      "id": "profile-email-input",
      "type": "Input",
      "props": [
        {"key": "label", "value": "Email Address"},
        {"key": "placeholder", "value": "you@example.com"},
        {"key": "type", "value": "email"},
        {"key": "value", "value": "jane@example.com"}
      ],
      "children": []
    },
    {
      "id": "profile-bio-textarea",
      "type": "Textarea",
      "props": [
        {"key": "label", "value": "Bio"},
        {"key": "placeholder", "value": "Tell us a little about yourself"},
        {"key": "value", "value": "Product designer and open source enthusiast. Based in Berlin."}
