    {
      "id": "profile-avatar",
      "type": "Avatar",
      "props": [
        {"key": "name", "value": "Jane Doe"},
        {"key": "size", "value": "lg"},
        {"key": "src", "value": "https://i.pravatar.cc/150?u=jane"}
      ],
      "children": []
    },
    {
      "id": "profile-save-btn",
      "type": "Button",
      "props": [
        {"key": "label", "value": "Save Profile"},
        {"key": "variant", "value": "default"}
      ],
      "children": []
    },
    {
      "id": "notifications-card",
      "type": "Card",
      "props": [
        {"key": "title", "value": "Notification Preferences"},
        {"key": "description", "value": "Choose how and when you receive updates from the platform"}
      ],
      "children": ["notif-email-check", "notif-push-check", "notif-digest-switch", "notif-update-btn"]
    },
    {
      "id": "notif-email-check",
      "type": "Checkbox",
      "props": [
        {"key": "label", "value": "Email notifications"},
        {"key": "checked", "value": "true"}
      ],
      "children": []
    },
    {
      "id": "notif-push-check",
      "type": "Checkbox",
      "props": [
        {"key": "label", "value": "Push notifications"},
        {"key": "checked", "value": "false"}
      ],
      "children": []
    },
    {
      "id": "notif-digest-switch",
      "type": "Switch",
      "props": [
        {"key": "label", "value": "Weekly digest"},
        {"key": "description", "value": "Receive a summary of your account activity every Monday morning"},
        {"key": "checked", "value": "true"}
      ],
      "children": []
    },
    {
      "id": "notif-update-btn",
      "type": "Button",
      "props": [
        {"key": "label", "value": "Update Notifications"},
        {"key": "variant", "value": "secondary"}
      ],
      "children": []
    },
    {
      "id": "privacy-card",
      "type": "Card",
      "props": [
        {"key": "title", "value": "Privacy Settings"},
