      ],
      "children": []
    },
    {
      "id": "privacy-activity-switch",
      "type": "Switch",
      "props": [
        {"key": "label", "value": "Show activity status"},
        {"key": "description", "value": "Let others see when you are online or your last active time"},
        {"key": "checked", "value": "false"}
      ],
      "children": []
    },
    {
      "id": "privacy-visibility-radio",
      "type": "RadioGroup",
      "props": [
        {"key": "label", "value": "Profile visibility"},
        {"key": "options", "value": "[\"Public\", \"Friends Only\", \"Private\"]"},
        {"key": "value", "value": "Public"}
      ],
      "children": []
    },
    {
      "id": "privacy-data-alert",
      "type": "Alert",
      "props": [
        {"key": "title", "value": "Your data"},
        {"key": "description", "value": "You can request a full copy of your personal data at any time. Processing typically takes 1-2 business days."},
        {"key": "variant", "value": "default"}
      ],
      "children": []
    },
    {
      "id": "privacy-export-btn",
      "type": "Button",
      "props": [
        {"key": "label", "value": "Download My Data"},
        {"key": "variant", "value": "outline"}
      ],
      "children": []
    }
  ]
